const cfg={a:{title:'6.3.1 Dezimalzahlen',intro:'Heute arbeitest du mit dem Komma. Immer nur ein kleiner Schritt.',steps:['Lies die Zahl langsam: 3.47 bedeutet 3 Ganze, 4 Zehntel und 7 Hundertstel.','Bei ·10 wird die Zahl grösser: das Komma wandert eine Stelle nach rechts.','Bei :10 wird die Zahl kleiner: das Komma wandert eine Stelle nach links.'],make(){let a=(Math.random()*80+10|0)/10,b=[10,100][Math.random()*2|0],mul=Math.random()<.5;return{q:`${a} ${mul?'·':':'} ${b} =`,a:mul?a*b:a/b,h:mul?'Multipliziere: Komma nach rechts.':'Dividiere: Komma nach links.'}},advice:['Schau die Stellenwerttafel und das Verschieben bei ·10 und :10 nochmals an.','Übe mit einer Zahl nach der anderen: erst Zehntel, dann Hundertstel.','Du bist sicher im Rechnen. Prüfe nur noch sorgfältig, ob das Komma richtig steht.']},b:{title:'6.3.2 Brüche und Dezimalzahlen',intro:'Ein Bruch kann wie ein Stück von 10 oder 100 gedacht werden.',steps:['Erweitere den Bruch, wenn möglich, auf Zehntel oder Hundertstel.','Schreibe den Nenner 10 als eine Stelle nach dem Komma, 100 als zwei Stellen.','Prüfe: Ist deine Dezimalzahl kleiner oder grösser als 1?'],make(){let d=[2,4,5,10,20,25][Math.random()*6|0],n=Math.random()*(d-1)+1|0;return{q:`${n}/${d} =`,a:n/d,h:'Erweitere auf einen Nenner mit 10 oder 100.'}},advice:['Schau dir nochmals an, wie du auf Zehntel oder Hundertstel erweiterst.','Schreibe einen Zwischenschritt auf: zum Beispiel 3/4 = 75/100 = 0.75.','Sehr gut. Übe als Nächstes auch Brüche, die grösser als 1 sind.']},c:{title:'6.3.3 Zahlen ordnen',intro:'Vergleiche nur zwei Zahlen auf einmal. Wandle Brüche in Dezimalzahlen um.',steps:['Schreibe beide Zahlen in derselben Form.','Vergleiche zuerst die Einer, dann die Zehntel, dann die Hundertstel.','Begründe deinen Entscheid mit einem kurzen Satz.'],make(){let d=[2,4,5,10][Math.random()*4|0],n=Math.random()*(d-1)+1|0,x=((Math.random()*90+5|0)/100);return{q:`Welche Zahl ist grösser: ${n}/${d} oder ${x}? (Bruch / Dezimalzahl)`,a:(n/d>x?'Bruch':'Dezimalzahl'),h:`Wandle ${n}/${d} zuerst in eine Dezimalzahl um.`}},advice:['Übe zuerst das Umwandeln von einfachen Brüchen in Dezimalzahlen.','Arbeite mit einem Zahlenstrahl und vergleiche zwei Zahlen nach der anderen.','Du kannst Zahlen sicher vergleichen. Begründe deine Antwort weiterhin mit einem Umwandlungsschritt.']}};
let k=document.body.dataset.topic,C=cfg[k],items=[];document.querySelector('#title').textContent=C.title;document.querySelector('#intro').textContent=C.intro;document.querySelector('#steps').innerHTML=C.steps.map((x,i)=>`<div class="step"><b>Schritt ${i+1}</b><br>${x}</div>`).join('');function num(x){return Math.round(x*1000)/1000}function fresh(){items=Array.from({length:10},()=>C.make());document.querySelector('#tasks').innerHTML=items.map((x,i)=>`<div class="task"><label>${i+1}. ${x.q}<small class="small"><br>${x.h}</small></label><input aria-label="Antwort ${i+1}" data-i="${i}" placeholder="Antwort"></div>`).join('');document.querySelector('#practiceResult').textContent=''}function check(){let good=0;document.querySelectorAll('#tasks input').forEach(e=>{let v=e.value.trim().replace(',','.');let a=items[e.dataset.i].a;if(typeof a==='string'?v.toLowerCase()===a.toLowerCase():Math.abs(Number(v)-num(a))<.001)good++});document.querySelector('#practiceResult').textContent=`${good} von 10 richtig. ${good<7?'Nimm dir Zeit und lies die Hinweise unter den Aufgaben.':'Gut gearbeitet!'}`}function checkpoint(){let qs=items.slice(0,5),good=0;qs.forEach((x,i)=>{let v=document.querySelector(`#cp${i}`).value.trim().replace(',','.');let a=x.a;if(typeof a==='string'?v.toLowerCase()===a.toLowerCase():Math.abs(Number(v)-num(a))<.001)good++});let level=good<=2?0:good<=4?1:2;document.querySelector('#feedback').classList.remove('hidden');document.querySelector('#feedbackText').innerHTML=`<h2>Dein Checkpoint: ${good} von 5</h2><p>${C.advice[level]}</p><p><b>Nächster Schritt:</b> ${level===0?'Wähle drei Übungsaufgaben und löse sie mit einer erwachsenen Person oder einem Lernpartner.':level===1?'Löse die Übungsaufgaben nochmals und schreibe bei jeder Aufgabe einen Zwischenschritt auf.':'Erkläre einer anderen Person, wie du eine Aufgabe löst.'}</p><p class="small">Dieses Blatt kannst du über den Button als PDF speichern oder ausdrucken.</p>`}fresh();document.querySelector('#refresh').onclick=fresh;document.querySelector('#check').onclick=check;document.querySelector('#cpcheck').onclick=checkpoint;document.querySelector('#print').onclick=()=>window.print();
